const Flow2 = ({ a, from, to, n = 5, speed = 0.6, s = 1, water }: { a: A; from: V3; to: V3; n?: number; speed?: number; s?: number; water?: boolean }) => <>{Array.from({ length: n }, (_, i) => { const u = (a.t * speed + i / n) % 1, k = Math.min(1, Math.sin(u * Math.PI) * 3) * s; const p: V3 = [mix(from[0], to[0], u), mix(from[1], to[1], u) + Math.sin(u * Math.PI) * 0.8, mix(from[2], to[2], u)]; return water ? <Ball key={i} p={p} s={0.2 * k} c="#8fe8ff" glow={0.9} cast={false} /> : <Coin key={i} p={p} s={0.9 * k} r={[0.9, u * 6, 0]} />; })}</>;
const Hose2 = ({ a, i }: { a: A; i: number }) => { const x = -0.5 + R(i, 61) * 9, z = -2.5 + R(i, 62) * 4; return <Rod a={[x, 0, z]} b={[x + Math.sin(a.t * 2 + i) * 0.18, 0.55 + R(i, 63) * 0.4, z]} w={0.06} c="#5aa84a" />; };
const Bar3x = ({ t, h, x, c, at = 0.3 }: { t: number; h: number; x: number; c: string; at?: number }) => { const v = Math.max(0.05, h * go(t, at, 0.9)); return <Box w={2.2} h={v} d={1.4} c={c} glow={0.2} p={[x, v / 2, 0]} rr={Math.min(0.25, v / 2)} />; };
const Loop = ({ a, ghost }: { a: A; ghost?: boolean }) => <Gr p={[0, 0, ghost ? -2 : 0]}><S g={G.torus(4.2, 0.2, Math.PI * 2 * Math.max(0.05, go(a.t, 0.1, 1.4)))} c="#8f7bff" glow={0.3} p={[0, 0.5, 0]} r={[Math.PI / 2, 0, 0]} o={ghost ? 0.5 : 1} /><Gr p={[Math.cos(a.t * 1.6) * 4.2, 0.6, Math.sin(a.t * 1.6) * 4.2]}><Ball s={0.5} c="#ffd23f" glow={0.8} /></Gr>{!ghost && <><House p={[-4.2, 0.6, 0]} s={0.9} /><Pile n={14} p={[4.2, 0.6, 0]} cols={3} /><S g={G.torus(0.8, 0.2)} c="#ffd23f" p={[0, 1.4, -4.2]} /></>}</Gr>;
